import {activePolicyPetitions,POLICY_PETITIONS,respondToPetition,petitionImpact,petitionReturnMonth} from './petitions.js?v=scenario-neighbor-status-1';
import {ORDINANCES} from './ordinances.js?v=scenario-neighbor-status-1';
export function showPolicyPetitions(ui,back,analysis=null){const c=ui.city(),pending=activePolicyPetitions(c),fmt=n=>Number(n||0).toLocaleString(undefined,{maximumFractionDigits:1});
 const impact=analysis?`<h3>Advisor impact analysis · ${ORDINANCES[analysis.id].name}</h3><p>Estimate at the current population, roads and development. No months have been simulated. Actual future growth, traffic and income may differ.</p><div class="table-scroll"><table><thead><tr><th>Measure</th><th>Current</th><th>With this decision</th></tr></thead><tbody>${[['balance','Monthly operating balance (§)'],['crime','Residential crime / 100'],['aura','Resident wellbeing / 100'],['healthTarget','Long-term life-expectancy target (years)'],['powerDemand','Connected power demand'],['waterDemand','City water demand']].map(([key,label])=>`<tr><td>${label}</td><td>${fmt(analysis.before[key])}</td><td>${fmt(analysis.after[key])}</td></tr>`).join('')}</tbody></table></div>`:'';
 ui.dialog('Meet policy petitioners',`<p>Residents propose policies in response to current city conditions. Consult the impact analysis, then accept, reject or dismiss. Accepting changes the ordinance immediately; recurring costs enter the monthly budget.</p>${impact}${pending.map(p=>`<article class="milestone"><small>${p.who}</small><h3>${p.enact?'Enact':'Repeal'} ${p.name}</h3><p>${p.why}</p><p>${p.description}</p>${p.monthlyCost?`<p>Current population cost: §${fmt(p.monthlyCost)}/month · §${fmt(p.monthlyCost*12)}/year while enacted.</p>`:''}<div class="actions"><button data-petition-impact="${p.id}">Advisor impact analysis</button><button class="primary" data-petition-id="${p.id}" data-petition-action="accepted">Accept · ${p.enact?'enact':'repeal'}</button><button data-petition-id="${p.id}" data-petition-action="rejected">Reject for 12 months</button><button data-petition-id="${p.id}" data-petition-action="dismissed">Dismiss for 6 months</button></div></article>`).join('')||'<p>No policy petitions are awaiting a decision. Requests depend on population, city conditions, current policy and your previous response.</p>'}<details><summary>Latest decisions</summary><ul>${Object.entries(c.petitions).map(([id,r])=>`<li>${ORDINANCES[id].name} · ${r.action} in city month ${r.month}. ${r.action==='accepted'?'If reversed, the request can return':'Eligible to return'} from month ${petitionReturnMonth(r)} if the issue persists.</li>`).join('')||'<li>No decisions yet.</li>'}</ul></details><p id="petitionError" role="alert"></p><button id="backPetitions">Back to civic services</button>`);
 document.querySelectorAll('[data-petition-impact]').forEach(b=>b.onclick=()=>{try{showPolicyPetitions(ui,back,{id:b.dataset.petitionImpact,...petitionImpact(c,b.dataset.petitionImpact)});}catch(e){document.getElementById('petitionError').textContent=e.message;}});
 document.querySelectorAll('[data-petition-action]').forEach(b=>b.onclick=()=>{try{respondToPetition(c,b.dataset.petitionId,b.dataset.petitionAction);ui.clearUndo();ui.update();ui.save();ui.notify('Petition '+b.dataset.petitionAction+'.');showPolicyPetitions(ui,back);}catch(e){document.getElementById('petitionError').textContent=e.message;}});document.getElementById('backPetitions').onclick=back;
}
